-- Baseline do Geitus: estrutura inicial consolidada do banco.
--
-- Este e o ponto de partida do schema. Reune, num unico baseline, as tabelas
-- ja existentes ate esta fase: empresa (tenant), usuario e produtos. As tabelas
-- dos proximos modulos (clientes, caixa, vendas/PDV, estoque, financeiro) serao
-- criadas em migrations proprias (V2, V3, ...) conforme cada etapa avancar.
--
-- Convencoes:
--  * Chave primaria interna: BIGINT GENERATED BY DEFAULT AS IDENTITY (DEC-015).
--    A aplicacao nunca fornece o id manualmente; o banco sempre gera.
--  * Isolamento por empresa (DEC-016): todo dado de negocio pertence a uma
--    empresa e nunca deve ser lido/alterado fora dela.
--  * Timestamps em TIMESTAMP sem timezone, padrao unico em todo o schema.

-- =====================================================================
-- Empresa (tenant): contexto da empresa autenticada.
-- =====================================================================
CREATE TABLE empresa (
    id            BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome          VARCHAR(150) NOT NULL,
    ativo         BOOLEAN      NOT NULL DEFAULT true,
    criado_em     TIMESTAMP    NOT NULL DEFAULT now(),
    atualizado_em TIMESTAMP
);

-- =====================================================================
-- Usuario: sempre vinculado a uma empresa (DEC-016).
-- senha_hash com VARCHAR(72): comporta o hash BCrypt (60 caracteres) com folga.
-- =====================================================================
CREATE TABLE usuario (
    id            BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    empresa_id    BIGINT       NOT NULL,
    nome          VARCHAR(150) NOT NULL,
    email         VARCHAR(180) NOT NULL,
    senha_hash    VARCHAR(72)  NOT NULL,
    perfil        VARCHAR(30)  NOT NULL,
    ativo         BOOLEAN      NOT NULL DEFAULT true,
    criado_em     TIMESTAMP    NOT NULL DEFAULT now(),
    atualizado_em TIMESTAMP,
    CONSTRAINT fk_usuario_empresa FOREIGN KEY (empresa_id) REFERENCES empresa (id),
    -- Unicidade de e-mail global nesta fase (simples). Se futuramente o produto
    -- precisar de e-mail unico por empresa, revisar esta constraint em migration propria.
    CONSTRAINT uq_usuario_email UNIQUE (email)
);

-- Indice para acelerar o lookup por empresa (consultas por tenant).
CREATE INDEX idx_usuario_empresa ON usuario (empresa_id);

-- =====================================================================
-- Produtos: itens fisicos, isolados por empresa (ver docs/modules/produtos.md).
-- =====================================================================
CREATE TABLE produtos (
    id              BIGINT         GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    empresa_id      BIGINT         NOT NULL,
    nome            VARCHAR(150)   NOT NULL,
    categoria       VARCHAR(100),
    unidade         VARCHAR(20),
    preco_venda     NUMERIC(12,2)  NOT NULL,
    custo           NUMERIC(12,2),
    -- NUMERIC(12,3): 3 casas decimais para suportar unidades fracionarias
    -- (ex.: kg, litro) no estoque minimo.
    estoque_minimo  NUMERIC(12,3),
    codigo_barras   VARCHAR(50),
    sku             VARCHAR(50),
    ativo           BOOLEAN        NOT NULL DEFAULT true,
    criado_em       TIMESTAMP      NOT NULL DEFAULT now(),
    atualizado_em   TIMESTAMP,
    CONSTRAINT fk_produto_empresa FOREIGN KEY (empresa_id) REFERENCES empresa (id),
    CONSTRAINT ck_produto_preco_venda_nao_negativo CHECK (preco_venda >= 0),
    CONSTRAINT ck_produto_custo_nao_negativo CHECK (custo IS NULL OR custo >= 0),
    CONSTRAINT ck_produto_estoque_minimo_nao_negativo CHECK (estoque_minimo IS NULL OR estoque_minimo >= 0),
    -- Unicidade de SKU e codigo de barras por empresa, apenas quando informados.
    -- No Postgres, UNIQUE trata multiplos valores NULL como nao-conflitantes
    -- (comportamento padrao SQL), entao uma constraint simples ja garante que
    -- produtos sem SKU/codigo de barras nao colidam entre si.
    CONSTRAINT uq_produto_empresa_sku UNIQUE (empresa_id, sku),
    CONSTRAINT uq_produto_empresa_codigo_barras UNIQUE (empresa_id, codigo_barras)
);

-- Indice para acelerar o lookup por empresa (mesmo padrao de idx_usuario_empresa).
CREATE INDEX idx_produto_empresa ON produtos (empresa_id);
